draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // person helping
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 60);
  ctx.lineTo(W/2 - 80, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 60);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();

  // stranger
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 60);
  ctx.lineTo(W/2 + 80, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 60);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // helping hand
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 80);
  ctx.lineTo(W/2 + 20, H/2 + 80 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
